"""Publish transparent numerical acceptance and current model assumptions."""
import json,hashlib
import numpy as np
from jump_rig import ROOT


def main():
    out=ROOT/'results/jump_contact_visualization';d=json.loads((out/'data.json').read_text());sources=[ROOT/f'results/contact_jump_scapula/{hz}hz' for hz in [600,1200]];runs=[]
    for folder in sources:
        summary=json.loads((folder/'tension_summary.json').read_text());z=dict(np.load(folder/'tensions.npz'));F=z['force_N'];ref=z['reference_N'];muscle_count=len(summary['names'])-4
        # Correct names/units in metadata without changing computed tensions.
        z.pop('unbounded_effort_coefficient',None);z['normalized_active_reference_force']=z['active_force_N']/ref
        summary['model_muscle_elements']=muscle_count;summary['force_unknowns']=len(ref);summary['internal_contact_unknowns']=summary['names'][muscle_count:];summary['shoulder_passive_model']='source standard architecture transferred by neutral path-length similarity; exponential reference spring';summary['scapular_joint']='two-point frictionless ellipsoid, neutral geometry fit; old rhythm targets projected to the surface manifold';summary['checks'].pop('maximum_effort_coefficient',None);summary['checks']['maximum_normalized_active_reference_force']=float(z['normalized_active_reference_force'][:,:muscle_count].max());summary['checks']['minimum_scapular_normal_force_N']=float(F[:,muscle_count:].min());summary['activation_or_EMG_prediction']=False
        summary['implementation_sha256']={name:hashlib.sha256((ROOT/'scripts'/name).read_bytes()).hexdigest() for name in ['build_contact_jump_tensions.py','conservative_ellipsoid_paths.py','shoulder_path_bridge.py','scapulothoracic_rig.py','tension_reference.py']};summary['shoulder_source_sha256']=hashlib.sha256((ROOT/'models/rmr/TSM_subject_noWeight.osim').read_bytes()).hexdigest()
        np.savez_compressed(folder/'tensions.npz',**z);(folder/'tension_summary.json').write_text(json.dumps(summary,indent=2));runs.append((summary,z,json.loads((folder/'verification.json').read_text())))
    quality=[json.loads((folder/'motion_quality.json').read_text()) for folder in sources]
    assert all(q['status']=='passed' for q in quality),'Rejected vertical-jump motion'
    a,b=runs;groups=[]
    for key in sorted(set(g['key'] for g in d['groups'])):
        ids=[i for g in d['groups'] if g['key']==key for i in g['indices']];end=min(a[1]['times'][-1],b[1]['times'][-1]);ia=a[1]['times']<=end;ib=b[1]['times']<=end;x=a[1]['force_N'][ia][:,ids].sum(1)/2;y=b[1]['force_N'][ib][:,ids].sum(1)/2;yy=np.interp(a[1]['times'][ia],b[1]['times'][ib],y);peak=max(float(x.max()),float(y.max()),1.)
        groups.append(dict(group=key,peak_600_N=float(x.max()),peak_1200_N=float(y.max()),relative_peak_difference=abs(float(x.max()-y.max()))/peak,curve_RMS_over_peak=float(np.sqrt(np.mean((x-yy)**2))/peak)))
    significant=[g for g in groups if max(g['peak_600_N'],g['peak_1200_N'])>=50]
    validation=dict(status='conditional_numerical_checks_passed',human_force_prediction_validated=False,mechanics_600=a[2]['checks'],mechanics_1200=b[2]['checks'],all_mechanics_gates_pass=all(a[2]['gates'].values()) and all(b[2]['gates'].values()),force_balance_max_error_Nm=max(r[0]['checks']['moment_balance_max_error'] for r in runs),minimum_scapular_normal_force_N=min(r[0]['checks']['minimum_scapular_normal_force_N'] for r in runs),scapular_contact_max_work_W=d['scapular_contact_max_power_W'],scapular_surface_residual=d['scapular_contact_max_surface_residual'],convergence=groups,convergence_rule='For groups with peak >=50 N: peak difference and interpolated curve RMS/peak <5%; numerical sensitivity only.',significant_force_groups_converged=all(g['relative_peak_difference']<.05 and g['curve_RMS_over_peak']<.05 for g in significant),muscle_elements=d['muscle_count'],render_groups=len(d['groups']),anatomical_registration_validated=False,contact_geometry='two medial scapular source landmarks, source-sized ellipsoid registered to neutral anatomy; center shift about 72 mm, requires anatomical review',landing_validated=False,force_law='total tension balance, standard passive springs, no active FLV limit or strength cap',identifiability='individual forces and antagonist recruitment depend on the selection rule; mechanical balance does not identify neural strategy')
    contact=np.load(sources[0]/'motion.npz')['contact_forces_N'];normal=contact[:,:,2];used=normal>1.;ratio=np.linalg.norm(contact[:,:,:2],axis=2)/np.maximum(normal,1e-9)
    validation['friction_model']=dict(type='16-face inner approximation of circular Coulomb cone',coefficient=.8,minimum_normal_N=float(normal.min()),maximum_euclidean_ratio_for_contact_force_above_1N=float(ratio[used].max()),note='All allowed contact forces stay inside the circular mu=0.8 cone; assumed shoe/ground friction, not measured.')
    validation['motion_quality']=quality
    validation['unidentified_plantar_support']=[dict(coordinates=r[0]['unidentified_joint_support_coordinates'],peak_Nm=r[0]['unidentified_support_peak_Nm']) for r in runs]
    validation['foot_intrinsic_and_fascia_force_solution_complete']=False
    from jump_model import create_rig
    rig=create_rig(json.loads((sources[0]/'setup.json').read_text())['rig_type']);motion=np.load(sources[0]/'motion.npz');ranges=[]
    for name,jid in rig.b.joints.items():
        if not name.startswith(('sternoclavicular','acromioclavicular')):continue
        x=motion['qpos'][:,rig.m.jnt_qposadr[jid]];lo,hi=rig.m.jnt_range[jid];ranges.append(dict(coordinate=name,range_rad=[float(x.min()),float(x.max())],legacy_coupled_envelope_rad=[float(lo),float(hi)],outside_legacy_envelope_rad=float(max(0,np.maximum(lo-x,x-hi).max()))))
    validation['scapular_angle_audit']=ranges;validation['ROM_gate_scope']='Independent coordinates only. New scapular contact coordinates leave parts of the legacy coupled-angle envelope; their anatomical ROM is not validated.'
    validation['status']='conditional_numerical_checks_passed' if validation['significant_force_groups_converged'] else 'mechanics_passed_muscle_sensitivity_unresolved'
    (out/'validation.json').write_text(json.dumps(validation,indent=2))
    mapping=json.loads((out/'render_mapping.json').read_text());coverage={key:sum(1 for m in mapping['meshes'] if m.get('key')==key and m.get('group_id')) for key in ['latissimus','trapezius','serratus','rhomboids','levator','quadriceps','soleus','abdominals']};assert all(coverage.values()),coverage
    (out/'coverage_checks.json').write_text(json.dumps(dict(status='passed',colored_meshes_by_major_group=coverage,unmodeled_intrinsic_foot_forces_invented=False),indent=2))
    method='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Jump model and assumptions</title><style>body{max-width:900px;margin:40px auto;padding:20px;font:18px/1.65 system-ui;background:#0d1726;color:#edf3fb}a{color:#8ce2d5}code{color:#eeb988}li{margin:10px 0}table{border-collapse:collapse}td,th{padding:10px;border:1px solid #465e76}</style><a href="index.html">Back to viewer</a><h1>What this jump calculation means</h1><p>This is a generic rigid-body, conditional muscle-tension reference. Numerical balance and sensitivity checks are distinct from validation of actual human movement or muscle recruitment. The motion ends before landing.</p><h2>Mechanical calculation</h2><ol><li>Declare movement targets, standing geometry, gravity and a square friction pyramid (component bounds 0.8 Fz; Euclidean ratio may reach 1.1314; this is not an exact circular mu=0.8 cone). Solve joint accelerations and nonnegative ground contact forces together, with exact six-dimensional floating-root Newton–Euler balance and sticking support. Ground force and COP are outputs of this controller-dependent reference. No floating-root motor or aerodynamic force is applied.</li><li>Release the feet for flight; external ground force is exactly zero. Airborne foot motion is a soft posture goal. Internal forces cannot change the whole-body ballistic momentum.</li><li>Use each segment's acceleration, gravity, inertia and external forces to form its force and moment balance. Independently sum body wrenches and joint cuts to cross-check the dynamics engine.</li><li>Compute muscle moment arms from geometric path derivatives. The added shoulder paths use the source ellipsoid path length, differentiated in a chest frame to preserve rigid-motion invariance and virtual work.</li><li>Balance five SC/AC rotations per side independently of GH rotation. Two medial scapular landmarks remain on a fitted thorax-fixed ellipsoid; solve nonnegative normal support forces as separate unknowns. This is a generic contact approximation, not the exact published scapulothoracic joint. The neutral center registration is about 72 mm and needs anatomical review.</li><li>Solve <code>R F + C N = required joint moments</code>, with nonnegative muscle tensions, passive spring floors, compressive scapular normals and a generic 20-degree GH reaction cone. Normalize by standard reference forces and use magnitude plus causal continuity to select one solution. No maximum strength limit is imposed.</li><li>Subtract muscle forces, internal scapular supports and external loads from segment requirements, then cut the articulated chain to obtain joint reaction forces. Joint surface colors show these resultants, not cartilage stress.</li></ol><h2>Assumptions and limits</h2><ul><li>180 cm, 90 kg generic segment geometry and reference inertial fractions. Visual anatomical surfaces are retargeted display assets; their mesh volume does not determine muscle strength.</li><li>438 muscle elements plus four scapula–thorax normal contact variables. Intrinsic foot muscles are absent. Unmapped tissues remain gray.</li><li>Reference passive curves, rigid tendons and standard architecture. LAT1's inherited nonphysical slack mapping is replaced by the upper-lat source architecture. Added shoulder architecture is transferred by neutral path-length similarity.</li><li>Only total tension is inferred. Active force–length–velocity feasibility, neural activation, fatigue, ligament/capsule deformation, stress, injury and microdamage are not computed.</li><li>Actual antagonist co-contraction is underdetermined. Passive tension and directional stability may require antagonist force; remaining sharing depends on the declared numerical criterion. A moving muscle can have zero selected active tension.</li><li>The force history is sampled at 30 Hz from 600/1200 Hz motion. Display is slowed to half speed; three replays are the same calculation. Means exclude landing and do not count replays as additional exercise volume.</li><li>Muscle colors sum element tensions within each displayed group. These scalar sums are neither a resultant force vector nor an activation percentage. Timeline rows average left and right group sums.</li><li>Visible articular bone surfaces are colored black-to-red by joint reaction magnitude, with a separate scale and no point markers. Muscles can occlude deeper joint surfaces. This does not locate peak tissue stress.</li></ul><h2>Evidence and sources</h2><p><a href="validation.json">Convergence, conservation and contact checks</a> · <a href="coverage_checks.json">Anatomical display coverage</a> · <a href="../contact_jump_scapula/600hz/tension_summary.json">Force-selection assumptions and source hashes</a></p><p>Shoulder attachments and reference architecture: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC6856649/">Seth, Dong, Matias and Delp (2019)</a>, <a href="https://github.com/ComputationalBiomechanicsLab/rmr-solver/tree/v1.1">RMR model v1.1</a>. Native full-body model: <a href="https://github.com/MyoHub/myo_sim">MyoSim</a>. <a href="CREDITS.md">Anatomical surface licenses</a>.</p></html>'''
    method=method.replace('a square friction pyramid (component bounds 0.8 Fz; Euclidean ratio may reach 1.1314; this is not an exact circular mu=0.8 cone)','a 16-face inner approximation of the circular Coulomb friction cone (mu=0.8)')
    method=method.replace('R F + C N = required joint moments','R F + C N + unidentified MTP support = required joint moments')
    method=method.replace('438 muscle elements plus four scapula–thorax normal contact variables. Intrinsic foot muscles are absent. Unmapped tissues remain gray.','438 muscle elements plus four scapula–thorax normal contact variables. MTP hinges are free and forefoot contacts follow the toe bodies. Intrinsic foot muscles and plantar-fascial support are absent: MTP net support moments remain explicitly unidentified, and toe muscle surfaces are gray. Extrinsic toe tensions are not released as validated tissue loads.')
    method=method.replace('<h2>Mechanical calculation</h2>','<h2>Upright revision and reliability</h2><p>The earlier rotating trajectory is rejected as a vertical-jump reference. New task checks independently inspect angular momentum at takeoff, physical thorax tilt in flight, launch direction and circular friction. New contact geometry has six points per foot and independent MTP hinges. The generic body remains 90 kg.</p><p><strong>Whole-body conservation checks pass, but some individual muscle histories remain sensitive to the time step.</strong> See the full convergence table; this is a diagnostic visualization, not a validated human force prediction. No muscle strength ceiling is used.</p><p><a href="calf_audit.html">Calf moment reconstruction and earlier error</a> · <a href="../contact_jump_scapula/600hz/motion_quality.json">Upright motion checks</a></p><h2>Mechanical calculation</h2>')
    method=method.replace('Subtract muscle forces, internal scapular supports and external loads','Subtract muscle forces, internal scapular supports, unresolved MTP couples and external loads')
    (out/'method.html').write_text(method,encoding='utf-8')
    print('CONTACT_VALIDATION',validation['significant_force_groups_converged'],'max peak error',max(g['relative_peak_difference'] for g in significant),'max RMS',max(g['curve_RMS_over_peak'] for g in significant),coverage,flush=True)

if __name__=='__main__':main()
